DEFAULTS = {"host": "localhost", "port": 8080, "debug": False}


def load_config(text):
    """Parse 'key = value' lines into a config dict."""
    # Start from a copy of DEFAULTS
    config = DEFAULTS.copy()

    for i, line in enumerate(text.splitlines()):
        line_num = i + 1  # 1-based indexing
        stripped_line = line.strip()

        # Skip blank lines and comments
        if not stripped_line or stripped_line.startswith('#'):
            continue

        # Split on the first '=' only
        parts = stripped_line.split('=', 1)

        # Requirement 5a: Check for structure (must have exactly one '=' split into two parts)
        if len(parts) != 2:
            raise ValueError(f"Parsing error on line {line_num}")

        key = parts[0].strip()
        value = parts[1].strip()

        # Requirement 5b: Check if key is in DEFAULTS
        if key not in DEFAULTS:
             raise ValueError(f"Unknown key '{key}' at line {line_num}")

        converted_value = value

        # Requirement 4 & 5c: Type conversion and validation
        if key == 'port':
            try:
                converted_value = int(value)
            except ValueError:
                raise ValueError(f"Invalid port value for line {line_num}")
        elif key == 'debug':
            lower_val = value.lower()
            if lower_val == "true":
                converted_value = True
            elif lower_val == "false":
                converted_value = False
            else:
                 raise ValueError(f"Invalid debug value for line {line_num}")

        config[key] = converted_value

    return config
