def summarize(rows):
    """rows: list of dicts with 'category' and 'amount' strings. Return {category: total}."""
    totals = {}
    for row in rows:
        # Normalize category: strip spaces and convert to lower case
        cat_raw = row.get("category", "")
        if not isinstance(cat_raw, str) or not cat_raw.strip():
            continue
        category = cat_raw.strip().lower()

        amt_raw = row.get("amount")

        # Validate and convert amount
        try:
            if not amt_raw:
                continue
            amount = float(amt_raw)
        except (ValueError, TypeError):
            # Skip if amount is empty or not a valid number
            continue

        # Accumulate total for the category
        totals[category] = totals.get(category, 0.0) + amount

    # Round each final total to 2 decimal places
    return {k: round(v, 2) for k, v in totals.items()}
